sp_widget.css:
.lib-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 12px;
}

.lib-card {
  display: block;
  text-decoration: none;
  border: 1px solid rgba(0,0,0,0.12);
  border-radius: 10px;
  overflow: hidden;
  background: #fff;
}

.lib-card:hover {
  border-color: rgba(0,0,0,0.25);
}

.lib-card-image {
  height: 240px;
  background: rgba(0,0,0,0.04);
  display: flex;
  align-items: center;
  justify-content: center;
}

.lib-card-image img {
  max-height: 100%;
  max-width: 100%;
  object-fit: cover;
}

.lib-card-image-placeholder {
  width: 60%;
  height: 70%;
  border: 1px dashed rgba(0,0,0,0.25);
  border-radius: 8px;
}

.lib-card-body {
  padding: 10px 12px 12px;
}

.lib-card-title {
  font-weight: 600;
  color: #1a1a1a;
  line-height: 1.2;
}

.lib-card-subtitle {
  margin-top: 6px;
  font-size: 12px;
  color: rgba(0,0,0,0.65);
}

.lib-empty, .lib-error {
  padding: 12px;
}

sp_widget.script:
(function () {
  data.items = [];
  data.error = "";

  var opts = options || {};

  var table = (opts.table || "").trim();
  if (!table) {
    data.error = "Missing option: table";
    return;
  }

  // Basic safety: avoid allowing arbitrary tables outside your scope unless you want that.
  // Comment out if you want true generic usage.
	// if (table.indexOf("x_662888_library_") !== 0) {
	// data.error = "Table not allowed";
	// return;
	// }


  var query = (opts.query || "").trim();
  var limit = parseInt(opts.limit, 10);
  if (isNaN(limit) || limit <= 0) limit = 50;
  if (limit > 200) limit = 200; // guardrail for portal performance

  var orderBy = (opts.order_by || "").trim();
  var orderDesc = (opts.order_desc === true || opts.order_desc === "true");

  var titleField = (opts.title_field || "name").trim();
  var subtitleField = (opts.subtitle_field || "").trim();
  var imageField = (opts.image_field || "").trim();

  var gr = new GlideRecord(table);
  if (!gr.isValid()) {
    data.error = "Invalid table: " + table;
    return;
  }

  if (query) gr.addEncodedQuery(query);

  if (orderBy) {
    if (orderDesc) gr.orderByDesc(orderBy);
    else gr.orderBy(orderBy);
  }

  gr.setLimit(limit);
  gr.query();

  while (gr.next()) {
    var item = {
      sys_id: gr.getUniqueValue(),
      display: gr.getDisplayValue(),
      title: "",
      subtitle: "",
      image_url: ""
    };

    // Title
    if (titleField && gr.isValidField(titleField))
      item.title = gr.getDisplayValue(titleField) || "";
    else
      item.title = gr.getDisplayValue() || "";

    // Subtitle (optional)
    if (subtitleField) {
      // Supports simple dot-walk like "author.name" IF the platform resolves display value.
      // If dot-walk fails, it falls back gracefully.
      try {
        item.subtitle = gr.getDisplayValue(subtitleField) || "";
      } catch (e) {
        item.subtitle = "";
      }
    }

    // Image (optional): for Image fields, display value often returns a URL.
    if (imageField && gr.isValidField(imageField)) {
      var img = gr.getDisplayValue(imageField);
      // If empty, keep empty. We'll show placeholder in HTML.
      item.image_url = img || "";
    }

    data.items.push(item);
  }
})();
